+
+  return (
+    <div className="form-field">
+      <label htmlFor={id}>
+        {label}
+        {required && <span className="req" aria-hidden="true">*</span>}
+      </label>
+      <input
+        ref={inputRef}
+        id={id}
+        name={id}
+        type={type}
+        required={required}
+        autoComplete={autoComplete}
+        placeholder={placeholder}
+        value={value}
+        onChange={onChange}
+        onBlur={onBlur}
+        aria-invalid={error ? "true" : undefined}
+        aria-describedby={describedBy}
+      />
+      {helperText && <span id={helperId} className="helper">{helperText}</span>}
+      {error && <span id={errorId} className="error">Error: {error}</span>}
+    </div>
+  );
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ name: "", email: "", phone: "" });
+  const [errors, setErrors] = useState({});
+  const [submitted, setSubmitted] = useState(false);
+
+  const refs = {
+    name: useRef(null),
+    email: useRef(null),
+    phone: useRef(null),
+  };
+
+  function validateField(field, val) {
+    const v = val.trim();
+    if (field === "name") {
+      if (!v) return "Enter your full name.";
+    }
+    if (field === "email") {
+      if (!v) return "Enter your email address.";
+      if (!EMAIL_RE.test(v)) return "Enter a valid email like name@example.com.";
+    }
+    if (field === "phone") {
+      if (v && !PHONE_RE.test(v)) return "Enter a valid phone number, e.g. +1 555-123-4567.";
+    }
+    return null;
+  }
+
+  function handleChange(field) {
+    return (e) => {
+      const val = e.target.value;
+      setValues((prev) => ({ ...prev, [field]: val }));
+      if (errors[field]) {
+        const next = validateField(field, val);
+        setErrors((prev) => ({ ...prev, [field]: next || undefined }));
+      }
+    };
+  }
+
+  function handleBlur(field) {
+    return () => {
+      const next = validateField(field, values[field]);
+      setErrors((prev) => ({ ...prev, [field]: next || undefined }));
+    };
+  }
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    setSubmitted(false);
+    const newErrors = {};
+    ["name", "email", "phone"].forEach((f) => {
+      const err = validateField(f, values[f]);
+      if (err) newErrors[f] = err;
+    });
+    setErrors(newErrors);
+
+    if (Object.keys(newErrors).length > 0) {
+      const firstInvalid = ["name", "email", "phone"].find((f) => newErrors[f]);
+      if (firstInvalid && refs[firstInvalid].current) {
+        refs[firstInvalid].current.focus();
+      }
+      return;
+    }
+
+    setSubmitted(true);
+    setValues({ name: "", email: "", phone: "" });
+  }
+
+  return (
+    <form className="contact-form" noValidate onSubmit={handleSubmit} aria-labelledby="form-heading">
+      <p className="required-legend">
+        Fields marked with <span className="req" aria-hidden="true">*</span> are required.
+      </p>
+
+      <Field
+        id="name"
+        label="Full name"
+        type="text"
+        required
+        autoComplete="name"
+        value={values.name}
+        onChange={handleChange("name")}
+        onBlur={handleBlur("name")}
+        error={errors.name}
+        inputRef={refs.name}
+      />
+
+      <Field
+        id="email"
+        label="Email address"
+        type="email"
+        required
+        autoComplete="email"
+        value={values.email}
+        onChange={handleChange("email")}
+        onBlur={handleBlur("email")}
+        error={errors.email}
+        inputRef={refs.email}
+      />
+
+      <Field
+        id="phone"
+        label="Phone number (optional)"
+        type="tel"
+        required={false}
+        autoComplete="tel"
+        placeholder="+1 555-123-4567"
+        value={values.phone}
+        onChange={handleChange("phone")}
+        onBlur={handleBlur("phone")}
+        error={errors.phone}
+        helperText="Include country code if outside the US. Digits, spaces, dashes, parentheses, and an optional leading + are allowed."
+        inputRef={refs.phone}
+      />
+
+      <button type="submit" className="submit">Send message</button>
+
+      <div role="status" aria-live="polite">
+        {submitted && (
+          <div className="success">Thanks! Your message has been sent. We'll be in touch soon.</div>
+        )}
+      </div>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <main id="main">
+      <h1 id="form-heading">Contact support</h1>
+      <p className="lede">Send us a message and a member of the support team will reply by email.</p>
+      <ContactForm />
+    </main>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<App />);
+
